<?php require __DIR__.'/config.php';require_admin();$id=(int)($_GET['id']??0);if($id<1)json_out(['error'=>'Invalid order.'],422);$s=$pdo->prepare("SELECT o.*,u.full_name,u.email FROM orders o JOIN users u ON u.id=o.customer_id WHERE o.id=?");$s->execute([$id]);$o=$s->fetch();if(!$o)json_out(['error'=>'Order not found.'],404);$s=$pdo->prepare('SELECT oi.*,CAST(oi.customizations AS CHAR) customizations_json FROM order_items oi WHERE order_id=? ORDER BY id');$s->execute([$id]);$o['items']=$s->fetchAll();foreach($o['items'] as &$i){$c=json_decode($i['customizations_json']??'{}',true)?:[];$parts=[];$labels=['flavor'=>'Flavor','sweetness'=>'Sweetness','size'=>'Size','rice_type'=>'Rice','pieces'=>'Chicken','extra_rice'=>'Extra rice','pearl'=>'Pearl','nata'=>'Nata','side'=>'Side','variant'=>'Variant','add_egg'=>'Egg','add_cheese'=>'Cheese','add_ham'=>'Ham','add_bacon'=>'Bacon','add_seaweed'=>'Seaweed'];foreach($c as $k=>$v)if($v)$parts[]=($labels[$k]??$k).': '.($v===true?'Yes':$v);$i['customizations_text']=implode(' · ',$parts);} $s=$pdo->prepare('SELECT id,method,amount,status,gateway_reference,payment_screenshot,created_at FROM payments WHERE order_id=? ORDER BY id DESC LIMIT 1');$s->execute([$id]);$o['payment']=$s->fetch()?:null;json_out(['order'=>$o]);?>